button { font: inherit; cursor: pointer; }
.mono, code, kbd, .id, .num { font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; }

/* ===== Layout ===== */
.page { max-width: 1280px; margin: 0 auto; padding: 0 32px; }
.row { display: flex; gap: 16px; }
.col { flex: 1 1 auto; min-width: 0; }
.grid { display: grid; gap: 16px; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-24 { gap: 24px; }
.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }

/* ===== Top navigation ===== */
.topnav {
  border-bottom: 1px solid #e2dccf;
  background: #f3ede4;
  padding: 14px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.brand {
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.02em;
