}

/* ===== Breadcrumb / page header ===== */
.crumbs {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #8a8276;
  padding: 18px 0 4px;
}
.crumbs .sep { margin: 0 8px; color: #c8bda9; }
.crumbs .active { color: #181613; }

.page-title {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.01em;
  line-height: 1.15;
  margin: 4px 0 8px;
}
.page-subtitle {
  color: #6a6356;
  max-width: 720px;
  margin: 0 0 24px;
  font-size: 13px;
  line-height: 1.55;
}

/* ===== Metric strip (4 columns) ===== */
.metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  padding: 12px 0 24px;
  border-top: 1px solid #e2dccf;
  border-bottom: 1px solid #e2dccf;
  margin-bottom: 24px;
}
.metric { padding: 8px 0; }
.metric .label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: #8a8276;
  margin-bottom: 6px;
}
.metric .value {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
}
.metric .delta {
  font-size: 11px;
  color: #6a6356;
