}
.delta.up { color: #2d7a4d; }
.delta.down { color: #c4452e; }
.delta::before { content: ""; display: inline-block; margin-right: 4px; }
.delta.up::before { content: "▲"; font-size: 8px; }
.delta.down::before { content: "▼"; font-size: 8px; }

/* ===== Cards ===== */
.card {
  background: #ffffff;
  border: 1px solid #e2dccf;
  border-radius: 6px;
  padding: 16px;
  margin-bottom: 16px;
}
.card-head {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}
.card-title {
  font-size: 14px; font-weight: 700; margin: 0;
  display: flex; align-items: center; gap: 8px;
}
.card-sub {
  font-size: 10px; text-transform: uppercase; color: #8a8276;
  letter-spacing: 0.1em;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 12px;
  background: #fff;
  border: 1px solid #d9cfba;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
  color: #181613;
  line-height: 1.2;
}
.btn:hover { background: #f7f1e5; }
.btn.primary {
  background: #e8593a; border-color: #d04829;
  color: #fff;
}
.btn.primary:hover { background: #d04829; }
.btn.ghost { background: transparent; border-color: transparent; color: #6a6356; }
.btn.sm { padding: 4px 8px; font-size: 11px; }

/* ===== Form controls ===== */
.input, .select {
  width: 100%;
  padding: 7px 10px;
  background: #fff;
  border: 1px solid #d9cfba;
  border-radius: 4px;
  font-size: 12px;
  color: #181613;
}
.input::placeholder { color: #a8a08e; }
.field-label {
  font-size: 10px; text-transform: uppercase; letter-spacing: 0.1em;
  color: #8a8276; margin-bottom: 4px; display: block;
}

/* ===== Chips & badges ===== */
.chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11px;
  background: #f1eadd;
  color: #4a4234;
  border: 1px solid #e2dccf;
