}
.chip .x { color: #b8ad97; font-size: 12px; margin-left: 2px; }
.chip.active { background: #fce4dc; color: #b03a1f; border-color: #f0c0b0; }
.chip.green { background: #e3f0e6; color: #2d7a4d; border-color: #c4dec9; }
.chip.amber { background: #fdf1d6; color: #8c6a16; border-color: #f0dca7; }
.chip.red { background: #fbe2dc; color: #a23b1f; border-color: #f3c5b6; }
.chip.gray { background: #ece4d4; color: #6a6356; }
.chip.blue { background: #e0e8f2; color: #2a4b78; border-color: #c2d2e6; }
.chip.violet { background: #ece2f0; color: #6b3a8e; border-color: #d8c5e0; }
.chip.pink { background: #fde2e8; color: #a8326b; border-color: #f5c2d0; }

.dot-icon {
  display: inline-block;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #2d7a4d;
  margin-right: 4px;
}
.dot-icon.red { background: #c4452e; }
.dot-icon.amber { background: #c69414; }
.dot-icon.gray { background: #a8a08e; }

/* ===== Tables ===== */
table { width: 100%; border-collapse: collapse; }
.tbl th, .tbl td {
  padding: 10px 8px;
  text-align: left;
  border-bottom: 1px solid #efe7d8;
  font-size: 12px;
  vertical-align: middle;
}
.tbl th {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #8a8276;
  border-bottom: 1px solid #e2dccf;
}
.tbl tr:hover td { background: #fbf6ec; }
.tbl td.num, .tbl th.num { text-align: right; font-variant-numeric: tabular-nums; }
.tbl .avatar-sm {
  width: 20px; height: 20px; border-radius: 50%;
  background: #f0d6c0; color: #b03a1f;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 600; margin-right: 6px;
}

/* ===== Page-specific composite ===== */
.maincols {
  display: grid;
