}
.tab.active {
  background: #ece3d3;
  color: #181613;
  border-color: #d9cfba;
}

/* ===== Toolbar ===== */
.toolbar {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  margin-bottom: 12px;
}
.toolbar .input { width: auto; flex: 1 1 200px; min-width: 160px; }
.toolbar .select { width: auto; flex: 0 1 160px; }

/* ===== Cohort heatmap ===== */
.heatmap {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
}
.heatmap .cell {
